            last[x] = i
            distinct.add(x)

        distinct_list = sorted(distinct)
        num_distinct = len(distinct_list)

        if num_distinct <= 1:
            results.append('0')
            continue

        max_len = 1
        current_len = 1

        for i in range(1, num_distinct):
            v = distinct_list[i-1]
            v_next = distinct_list[i]

            if last[v] < first[v_next]:
                current_len += 1
            else:
                current_len = 1

            max_len = max(max_len, current_len)

        results.append(str(num_distinct - max_len))

    return '\n'.join(results)
