def find_centroid(n, adj):
    """Find centroid of the tree."""
    total_nodes = n
    subtree_sizes = [0] * (n + 1)

    # BFS to compute subtree sizes
    visited = [False] * (n + 1)
    queue = deque([1])
    visited[1] = True
    order = []

    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in adj[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

    # Compute sizes bottom-up
    for node in reversed(order):
        size = 1
        for neighbor in adj[node]:
            size += subtree_sizes[neighbor]
        subtree_sizes[node] = size

    # Binary search for centroid
    for candidate in order:
        for neighbor in adj[candidate]:
            if subtree_sizes[neighbor] > total_nodes // 2:
                break
        else:
            max_comp = max(subtree_sizes[candidate], total_nodes - subtree_sizes[candidate])
            if max_comp <= total_nodes // 2:
                return candidate

    return 1

