    def bfs_farthest(start_node):
        dist = [-1] * (n + 1)
        dist[start_node] = 0
        visited = [False] * (n + 1)
        visited[start_node] = True
        parent = {start_node: None}
        queue = deque([start_node])

        farthest = start_node
