def solution(s):
    # Parse input
    lines = s.strip().split('\n')
    n, k = map(int, lines[0].split())
    sequence = list(lines[1])

    if k > n:
        return "NO"

    # We'll use DFS with pruning to find a valid assignment
    # State: (index, current_balance)
    # balance = wins - losses

    result = []

    def can_complete(idx, balance):
        # Check constraint: balance should not be k (in absolute) before end
        if abs(balance) == k:
            return idx == n - 1

        if idx == n:
            return abs(balance) == k

        char = sequence[idx]

        # Determine allowed moves
        if char == '?':
            moves = [('W', balance + 1), ('L', balance - 1), ('D', balance)]
        elif char == 'W':
            moves = [('W', balance + 1)]
        elif char == 'L':
            moves = [('L', balance - 1)]
        else:  # 'D'
            moves = [('D', balance)]

        for move_char, new_balance in moves:
            # Check constraint for this move
            if abs(new_balance) == k and idx + 1 < n:
                continue  # Cannot reach k before the end

            # Recursively check if we can complete from here
            if can_complete(idx + 1, new_balance):
                return True

        return False

    def build_solution(idx, balance):
        if idx == n:
            return abs(balance) == k

        char = sequence[idx]

        if char == '?':
            moves = [('W', balance + 1), ('L', balance - 1), ('D', balance)]
        elif char == 'W':
            moves = [('W', balance + 1)]
        elif char == 'L':
            moves = [('L', balance - 1)]
        else:
            moves = [('D', balance)]

        for move_char, new_balance in moves:
            if abs(new_balance) == k and idx + 1 < n:
                continue

            if can_complete(idx + 1, new_balance):
                result.append(move_char)
                return build_solution(idx + 1, new_balance)

        return False

    if can_complete(0, 0):
        build_solution(0, 0)
        return ''.join(result) + '\n'
    else:
        return "NO\n"


