def compute_tree_weight(n, weights, edges):
    """
    For a valid tree with the given structure:
    1. Find the node with minimum weight (useful for verification)
    2. Calculate degree term: sum of deg[u] * weight[u]
    3. Calculate edge term: sum of ceil(log2(dist)) * min(weight[u], weight[v])
    """
    min_weight = min(weights)
    root_idx = weights.index(min_weight)

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)

    # BFS from root to compute node distances
    dist = [-1] * n
    dist[root_idx] = 0
    queue = [root_idx]
    parent = [-1] * n

    visited = [False] * n
    visited[root_idx] = True

    while queue:
        u = queue.pop(0)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                dist[v] = dist[u]
                parent[v] = u
                queue.append(v)

    degree_term = 0
    for i in range(n):
        degree_term += len(adj[i]) * weights[i]

    edge_term = 0
    for u, v in edges:
        u_adj = u - 1
        v_adj = v - 1
        min_weight_uv = min(weights[u_adj], weights[v_adj])
        edge_term += min_weight_uv

    return degree_term + edge_term


