                    v = get_node(abs(lj), lj > 0)
                    adj[u].append(v)
                    rev_adj[v].append(u)

    # Kosaraju's algorithm for SCC
    topo = []
    visited = [False] * num_nodes

    def dfs_topo(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs_topo(v)
        topo.append(u)

    for i in range(num_nodes):
        if not visited[i]:
            dfs_topo(i)

    topo.reverse()
    visited2 = [False] * num_nodes
    scc_id = [0]
    scc_of = [0] * num_nodes

    def dfs_scc(u):
        visited2[u] = True
        for v in rev_adj[u]:
            if not visited2[v]:
                dfs_scc(v)
        scc_id[0] += 1
        scc_of[u] = scc_id[0] - 1

    for u in topo:
        if not visited2[u]:
            dfs_scc(u)

    # Check satisfiability
    for i in range(m):
        if scc_of[2 * i] == scc_of[2 * i + 1]:
            return "NO\n"

    # Generate satisfying assignment
    assignment = [0] * m
    for i in range(m):
        # If SCC[Li] < SCC[¬Li], Li must be true
        assignment[i] = 1 if scc_of[2 * i] < scc_of[2 * i + 1] else 0

    return "YES\n" + ''.join(map(str, assignment))
