The key insight is:
1. Bridges between island u and v (u≠v): 2^gcd(u,v) bridges
2. Island transitions use matrix exponentiation for efficiency (t up to 10^18)
3. For t=1, ans[i] = a[i], but there's a special formula needed
4. The XOR sum requires careful handling

Let me implement a solution based on matrix exponentiation with the transition structure:

```python
import math
import sys

MOD = 1051131

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def matrix_multiply(A, B, n):
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            for j in range(n):
                if A[i][k] != 0 and B[k][j] != 0:
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def matrix_power(A, p, n):
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    while p > 0:
        if p & 1:
            result = matrix_multiply(result, A, n)
        A = matrix_multiply(A, A, n)
        p >>= 1
    return result

def solve():
    line1 = input().split()
    m, t, s = int(line1[0]), int(line1[1]), int(line1[2])

    line2 = list(map(int, input().split()))
    a = line2[:]

    n = 2 * m

    # Generate remaining a values
    for i in range(len(a), n):
        a.append((101 * a[-1] + 10007) % MOD)

    if t == 1:
        ans_sum = 0
        for val in a:
            ans_sum ^= val
        return str(ans_sum % MOD) + '\n'

    # Build transition matrix
    # M[i][j] = 2^gcd(i+1, j+1) for i != j, 1 for i == j
    M = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                M[i][j] = 1
            else:
                M[i][j] = pow(2, gcd(i + 1, j + 1), MOD)

    # Compute M^(t-1)
    M_powered = matrix_power(M, t - 1, n)

    # Apply to initial vector a
    final_ans = [0] * n
    for i in range(n):
        total = 0
        for j in range(n):
            val = (M_powered[i][j] * a[j]) % MOD
            total = (total + val) % MOD
        final_ans[i] = total

    # Output XOR sum
    xor_sum = 0
    for val in final_ans:
        xor_sum ^= val

    return str(xor_sum % MOD) + '\n'

if __name__ == "__main__":
    import sys
    print(solve(), file=sys.stdout)
