Looking at this problem, I need to:
1. Divide numbers into two sets A and B
2. For set A: if x is in A, then (a-x) must also be in A
3. For set B: if x is in B, then (b-x) must also be in B

This can be solved using Union-Find to group elements that must be in the same set, then checking if each component can be validly assigned.

```python
import sys
import os

sys.setrecursionlimit(200000)

def solution(input_str):
    """
    Solution for dividing numbers into sets A and B with complement constraints.
    """
    try:
        lines = input_str.strip().split('\n')
        if len(lines) < 2:
            return "NO"

        n, a, b = map(int, lines[0].split())
        p = list(map(int, lines[1].split()))
    except:
        return "NO"

    if n == 0:
        return "YES\n"

    p_set = set(p)
    p_map = {v: i for i, v in enumerate(p)}

    # Union-Find data structure
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    # Build connected components based on complement constraints
    for i in range(n):
        x = p[i]
        # If a-x exists, x and (a-x) must be in the same component (both in A)
        if (a - x) in p_map:
            union(i, p_map[a - x])
        # If b-x exists, x and (b-x) must be in the same component (both in B)
        if (b - x) in p_map:
            union(i, p_map[b - x])

    # Group elements by their component root
    components = {}
    for i in range(n):
        root = find(i)
        if root not in components:
            components[root] = []
        components[root].append(i)

    result = [0] * n
    possible = True

    # For each component, check if it can be assigned validly
    for root, indices in components.items():
        # Check if all elements in component can go to A (i.e., all have their a-complements)
        can_be_a = True
        for idx in indices:
            x = p[idx]
            if (a - x) not in p_set:
                can_be_a = False
                break

        # Check if all elements in component can go to B (i.e., all have their b-complements)
        can_be_b = True
        for idx in indices:
            x = p[idx]
            if (b - x) not in p_set:
                can_be_b = False
                break

        # Assignment logic:
        # - If both are possible, choose A (0)
        # - If only A is possible, must choose A (0)
        # - If only B is possible, must choose B (1)
        # - If neither, impossible
        if can_be_a and can_be_b:
            assignment = 0
        elif can_be_a:
            assignment = 0
        elif can_be_b:
            assignment = 1
        else:
            possible = False
            break

        for idx in indices:
            result[idx] = assignment

    if possible:
        return f"YES\n{' '.join(map(str, result))}\n"
    else:
        return "NO\n"
```

