def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            row = list(map(int, lines[idx].split()))
            idx += 1
            matrix.append(row)

        ops = lines[idx]
        idx += 1

        def invert_row(row):
            m_len = len(row)
            inv = [0] * m_len
            for i in range(m_len):
                inv[row[i]] = i
            return inv

        def invert_col(col):
            n_len = len(col)
            inv = [0] * n_len
            for i in range(n_len):
                inv[col[i]] = i
            return inv

        for op in ops:
            if op == 'R':
                for i in range(n):
                    matrix[i] = [matrix[i][-1]] + matrix[i][:-1]
            elif op == 'L':
                for i in range(n):
                    matrix[i] = matrix[i][1:] + [matrix[i][0]]
            elif op == 'D':
                first_row = matrix[0][:]
                for i in range(n - 1):
                    matrix[i] = matrix[i + 1][:]
                matrix[n - 1] = first_row
            elif op == 'U':
                last_row = matrix[n - 1][:]
                for i in range(n - 1, 0, -1):
                    matrix[i] = matrix[i - 1][:]
                matrix[0] = last_row
            elif op == 'I':
                for i in range(n):
                    matrix[i] = invert_row(matrix[i])
            elif op == 'C':
                for j in range(n):
                    col = [matrix[i][j] for i in range(n)]
                    inv_col = invert_col(col)
                    for i in range(n):
                        matrix[i][j] = inv_col[i]

        result_lines = []
        for i in range(n):
            result_lines.append(" ".join(map(str, matrix[i])))
        results.append("\n".join(result_lines))
        results.append("")

    return "\n".join(results)


