def solution(input_str):
    MOD = 10**9 + 7

    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    q = int(lines[0])
    queries = []
    max_n = 0

    for i in range(1, q + 1):
        parts = lines[i].split()
        r, n = int(parts[0]), int(parts[1])
        queries.append((r, n))
        max_n = max(max_n, n)

    # Sieve for smallest prime factor
    spf = list(range(max_n + 1))
    for i in range(2, int(max_n**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_n + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Count distinct prime factors  
    num_distinct = [0] * (max_n + 1)
    for i in range(2, max_n + 1):
        p = spf[i]
        if i // p % p != 0:
            num_distinct[i] = num_distinct[i // p] + 1
        else:
            num_distinct[i] = num_distinct[i // p]

    # f0(n) = 2^(distinct_prime_factors)
    # For r > 0, based on patterns in competitive programming:
    # f_r(n) = f0(n) * C.ombinations involving r and total_prime_factors

    # Precompute factorials for combinations
    max_prime_total = 0
    for i in range(1, max_n + 1):
        # Count total prime factors (with multiplicity)
        total = 0
        temp = i
        while temp > 1:
            total += 1
            temp //= spf[temp]
        if total > max_prime_total:
            max_prime_total = total

    # C(n, k) precomputation
    MAX_VAL = max(max_prime_total + max_n, max(0, 1000000))
