def solution(input_data):
    import sys
    from collections import defaultdict, deque

    n = int(input_data.split('\n')[0])
    adj = defaultdict(list)
    node_list = []

    lines = input_data.strip().split('\n')[1:]
    for line in lines:
        if line.strip():
            u, v = map(int, line.strip().split())
            adj[u].append(v)
            adj[v].append(u)
            node_list.extend([u, v])

    # Find centroid
    def solve_centroid():
        sz = [0] * (n + 1)

        def calc(u, p):
            sz[u] = 1
            for v in adj[u]:
                if v != p:
                    calc(v, u)
                    sz[u] += sz[v]

        calc(1, 0)

        def find(u, p):
            for v in adj[u]:
                if v != p and sz[v] > n // 2:
                    return find(v, u)
            return u

        return find(1, 0)

    centroid = solve_centroid()

    # BFS from centroid
    d = {centroid: 0}
    p = {centroid: 0}
    q = deque([centroid])

    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in d:
                d[v] = d[u] + 1
                p[v] = u
                q.append(v)

    # Group nodes by their first-neighbor from centroid
    branch_nodes = defaultdict(list)
    for node in range(1, n + 1):
        if node == centroid:
            continue
        path = [node]
        while p[path[-1]] != centroid:
            path.append(p[path[-1]])
        branch_nodes[path[-1]].append(node)

    # Sort branches by size
    for b in branch_nodes:
        branch_nodes[b].sort(key=lambda x: d[x], reverse=True)

    sorted_branches = sorted(branch_nodes.keys(), key=lambda x: len(branch_nodes[x]), reverse=True)

    # Select two non-adjacent branches
    b1, b2 = sorted_branches[0], sorted_branches[1]
    candidates1 = branch_nodes[b1]
    candidates2 = branch_nodes[b2]

    # Select pairs ensuring distinct vertices
    p1_list = [candidates1[0]]
    p2_list = [candidates2[0]]

    for i in range(1, len(candidates1)):
        if candidates1[i] not in p1_list and candidates1[i] not in p2_list:
            p1_list.append(candidates1[i])
            if len(p1_list) >= 2:
                break

    for i in range(1, len(candidates2)):
        if candidates2[i] not in p1_list and candidates2[i] not in p2_list:
            p2_list.append(candidates2[i])
            if len(p2_list) >= 2:
                break

    # Fill missing if needed
    missing1 = [x for x in range(1, n + 1) if x not in set(p1_list)]
    missing2 = [x for x in range(1, n + 1) if x not in set(p2_list)]

    while len(p1_list) < 2:
        for m in missing1:
            p1_list.append(m)
            break

    while len(p2_list) < 2:
        for m in missing2:
            p2_list.append(m)
            break

    x1, y1 = p1_list[0], p1_list[1]
    x2, y2 = p2_list[0], p2_list[1]

    return f"{x1} {y1}\n{x2} {y2}"
